export function StaleState({
  message = "{{message}}",
  lastUpdated = "{{lastUpdated}}",
  severity = "{{severity}}",
  showRefresh = {{showRefresh}},
}) {
  const palette = {
    notice: { bg: "color-mix(in srgb, #D9C8F0 40%, #FAF7F2)", border: "#8A6FBF", icon: "#8A6FBF" },
    warning: { bg: "color-mix(in srgb, #E8A020 18%, #FAF7F2)", border: "#B4790A", icon: "#B4790A" },
  }[severity] ?? { bg: "#FAF7F2", border: "#8A6FBF", icon: "#8A6FBF" };
  return (
    <div role="status" aria-live="polite" style={{ display: "flex", alignItems: "center", gap: 10, maxWidth: 380,
      padding: "10px 14px", boxSizing: "border-box", borderRadius: 9, font: "13px/1.4 system-ui, sans-serif",
      color: "#241430", border: `1px solid ${palette.border}`, background: palette.bg }}>
      <span aria-hidden="true" style={{ fontSize: 16, flexShrink: 0, color: palette.icon }}>⟳</span>
      <div style={{ flex: 1 }}>
        <p style={{ margin: 0, fontWeight: 700 }}>{message}</p>
        <p style={{ margin: "2px 0 0", color: "#241430b3", fontSize: 11.5 }}>Updated {lastUpdated}</p>
      </div>
      {showRefresh && (
        <button type="button" style={{ border: "1px solid #241430", background: "transparent", color: "#241430",
          borderRadius: 6, fontWeight: 600, fontSize: 11.5, padding: "5px 10px", cursor: "pointer", whiteSpace: "nowrap" }}>Refresh</button>
      )}
    </div>
  );
}
